describe('Error Messages Accessibility', () => {
    beforeEach(() => {
        cy.visit('/'); // Replace with the actual URL of the application
    });

    it('should display error message that is screen-reader accessible', () => {
        // Trigger an error condition
        cy.get('input[name="username"]').type('invalidUser');
        cy.get('form').submit();

        // Check for the presence of the error message
        cy.get('.error-message').should('be.visible')
            .and('have.attr', 'role', 'alert')
            .and('contain', 'Invalid username or password');
    });

    it('should not display error message when input is valid', () => {
        // Trigger a valid input condition
        cy.get('input[name="username"]').type('validUser');
        cy.get('input[name="password"]').type('validPassword');
        cy.get('form').submit();

        // Check that no error message is displayed
        cy.get('.error-message').should('not.exist');
    });
});
